32	/** Get the current user ID, works in both foreground and background */
33	const getCurrentUserId = (): string | null => {
34	  // Try to get from active instance first (foreground)
35	  const instanceUserId = MatrixCore.instance?.userId();
36	  if (instanceUserId) return instanceUserId;
37	
38	  // Fall back to stored credentials (works in background)
39	  const credentials = MatrixStorage.getLoginCredentials();
40	  return credentials?.userId || null;
41	};
42	
43	/**
44	 * Ensure MatrixService is initialized for background decryption
45	 * Uses lightweight initialization that doesn't start sync service
46	 */
47	const ensureServiceInitialized = async (): Promise<boolean> => {
48	  const notificationClient = MatrixNotificationService.getNotificationClient();
49	  if (notificationClient) return true;
50	
51	  // Foreground: create notification client if possible
52	  if (MatrixCore.instance) {
53	    const client = await MatrixNotificationService.ensureNotificationClient();
54	    return !!client;
55	  }
56	
57	  // Try to restore session with lightweight background method
58	  try {
59	    const restored = await AuthService.restoreSessionForBackground();
60	    return restored;
61	  } catch (error) {
62	    console.error("[Push] Failed to restore session:", error);
63	    return false;
64	  }
65	};
