67	const isCurrentlyViewingRoom = (roomId: string): boolean => {
68	  if (AppState.currentState !== "active") return false;
69	  if (!NavigationContainerRef?.isReady()) return false;
70	
71	  try {
72	    const route = NavigationContainerRef?.getCurrentRoute();
73	    return route?.name === "room" && route.params?.roomId === roomId;
74	  } catch {
75	    return false;
76	  }
77	};
78	
79	const handleReceivedMessage = async (
80	  message: FirebaseMessagingTypes.RemoteMessage,
81	) => {
82	  const data = message.data as unknown as NotificationData;
83	  if (!data) return;
84	
