import { NativeEventEmitter, NativeModules, Platform } from "react-native";
import { MatrixNotificationService } from "./MatrixNotificationService";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";

/**
 * Handles the VoIP push token lifecycle on iOS.
 *
 * Flow:
 *  PKPushRegistry (native) → VoIPPushModule emits "voIPPushTokenUpdated"
 *  → this service registers the token as a VoIP pusher with the Matrix homeserver
 *  → Sygnal uses the VoIP APNs certificate to wake the app even when killed
 */
export const VoIPPushService = {
  setup() {
    if (Platform.OS !== "ios") return;

    const { VoIPPushModule } = NativeModules;
    if (!VoIPPushModule) return;

    const emitter = new NativeEventEmitter(VoIPPushModule);

    emitter.addListener("voIPPushTokenUpdated", async (token: string) => {
      if (!token || !MatrixCore.instance) return;
      try {
        await MatrixNotificationService.setVoIPPusher(token);
      } catch (error) {
        console.error("[VoIP] Failed to register VoIP pusher:", error);
      }
    });
  },
};

