import { Dimensions, Platform } from "react-native";
import { SIDEBAR_WIDTH } from "shared/const/sidebar-width";

export const isIpad = (): boolean => Platform.OS === "ios" && Platform.isPad;

export const adaptSize = (phone: number, ipad = phone): number =>
  isIpad() ? ipad : phone;

/** Returns the usable content width for the given context.
 * - Timeline media (isTimeline=true): half the total screen width so images
 *   and videos don't fill the entire right pane on large iPads.
 * - All other content: the full right-pane width (total minus sidebar). */
export const effectiveWindowWidth = (isTimeline?: boolean): number => {
  const { width } = Dimensions.get("window");
  if (isIpad()) return isTimeline ? width / 2 : width - SIDEBAR_WIDTH;
  return width;
};

